mapper.select:
SELECT b.id,b.isbn,b.title,b.author,b.category_id categoryId,c.name categoryName, b.publisher_id publisherId,p.name publisherName, b.price,b.publish_date publishDate, b.intro,b.cover, (SELECT COUNT(*) FROM book_copy bc WHERE bc.book_id =b.id) AS totalCopies, (SELECT COUNT(*) FROM book_copy bc WHERE bc.book_id =b.id AND bc.STATUS='available') AS availableCopies, (SELECT COUNT(*) FROM borrow_record br JOIN book_copy bcc ON br.copy_id=bcc.id WHERE bcc.book_id=b.id)AS borrowCount FROM book b LEFT JOIN publisher p ON b.publisher_id=p.id LEFT JOIN category c ON b.category_id = c.id
ORDER BY b.price ASC ORDER BY b.price DESC ORDER BY borrowCount DESC ORDER BY b.id DESC
LIMIT #{offset}, #{size}
